import AssetsInfo from '@/components/deepbook/AssetsInfo'
import DeepbookChart from '@/components/deepbook/DeepbookChart'
import FooterBlock from '@/components/deepbook/FooterBlock'
import OrderBookBlock from '@/components/deepbook/OrderBookBlock'
import TopDataBlock from '@/components/deepbook/TopDataBlock'
import TradeBlock from '@/components/deepbook/TradeBlock'
import TradeTableBlock from '@/components/deepbook/TradeTableBlock'
import useDocumentSize from '@cetus/hooks/src/useDocumentSize'
import { Box, VStack } from '@chakra-ui/react'
import { IJsonModel, Layout, Model, TabNode } from 'flexlayout-react'
import 'flexlayout-react/style/light.css'
import { useEffect, useMemo } from 'react'

interface DeepBookPCProps {
  currentDeepBookPool: any
  deepBookPools: any[]
  currentAccount: any
  currentBalanceManagerInfo: any
}

function DeepBookPC({ currentDeepBookPool, deepBookPools, currentAccount, currentBalanceManagerInfo }: DeepBookPCProps) {
  const { size } = useDocumentSize()

  // ==================== FlexLayout 配置 ====================
  const model = useMemo(
    () =>
      Model.fromJson({
        global: {
          tabEnableClose: false,
          tabSetEnableTabStrip: false
        },
        layout: {
          type: 'column',
          children: [
            {
              type: 'column',
              weight: 85,
              children: [
                {
                  type: 'tabset',
                  weight: 8,
                  minWidth: 800,
                  minHeight: 64,
                  maxHeight: 64,
                  children: [{ type: 'tab', component: 'TopDataBlock', zIndex: 9 }],
                  enableDivide: false // 禁用分割条
                },
                {
                  type: 'row',
                  weight: 75,
                  zIndex: 8,
                  config: { splitterEnabled: false },
                  children: [
                    {
                      type: 'tabset',
                      weight: 83,
                      minWidth: 288,
                      children: [{ type: 'tab', component: 'ChartBlock' }]
                    },
                    {
                      type: 'tabset',
                      weight: 17,
                      minWidth: 328,
                      minHeight: 360,
                      children: [{ type: 'tab', component: 'OrderBookBlock' }]
                    }
                  ]
                },
                {
                  type: 'tabset',
                  weight: 36,
                  minHeight: size?.h < 600 ? 500 : 368,
                  children: [{ type: 'tab', component: 'TradeTableBlock' }]
                }
              ]
            },
            {
              type: 'column',
              weight: 15,
              children: [
                {
                  type: 'tabset',
                  weight: 100,
                  minWidth: 352,
                  minHeight: 808,
                  children: [
                    {
                      type: 'tab',
                      component: 'TradeBlock',
                      name: 'TradeBlock'
                    }
                  ]
                }
              ]
            }
          ]
        }
      } as IJsonModel),
    [size?.h]
  )

  // ==================== FlexLayout 工厂函数 ====================
  const factory = (node: TabNode) => {
    const component = node.getComponent()
    useEffect(() => {
      if (node.getComponent() === 'TopDataBlock') {
        setTimeout(() => {
          const splitters = document.querySelectorAll('.flexlayout__splitter')
          if (splitters.length > 0) {
            // 隐藏第一个分割条（TopDataBlock上方的）
            // ;(splitters[0] as HTMLElement).style.display = 'none'
            ;(splitters[0] as HTMLElement).style.backgroundColor = 'transparent'
            ;(splitters[0] as HTMLElement).style.pointerEvents = 'none'
          }
        }, 0)
      }
    }, [])
    switch (component) {
      case 'TopDataBlock':
        return (
          <Box h="100%" w="100%">
            <TopDataBlock />
          </Box>
        )
      case 'TradeBlock':
        return (
          <Box h="100%" w="100%">
            <TradeBlock />
            <Box h="8px" bg="bg_primary" />
            <AssetsInfo />
          </Box>
        )
      case 'ChartBlock':
        return (
          <Box h="100%" w="100%">
            <DeepbookChart currentDeepBookPool={currentDeepBookPool} />
          </Box>
        )
      case 'OrderBookBlock':
        return (
          <Box h="100%" w="100%">
            <OrderBookBlock />
          </Box>
        )
      case 'TradeTableBlock':
        return (
          <Box h="100%" w="100%">
            <TradeTableBlock />
          </Box>
        )
      case 'FooterBlock':
        return (
          <Box h="100%" w="100%">
            <FooterBlock />
          </Box>
        )
      default:
        return null
    }
  }

  return (
    <VStack minWidth="1160px" w="100%" minHeight="648px" h={size?.h - 80} overflow={size?.h < 650 ? 'unset' : 'unset'}>
      <Box minH="808px" h={size?.h - 80 - 48} w="100%" bg="bg_secondary" position="relative" zIndex="5">
        <Layout model={model} factory={factory} realtimeResize={true} />
      </Box>
      <FooterBlock />
    </VStack>
  )
}

export default DeepBookPC
