import envConfigs from '@cetus/types/src/config/envConfigs'
import { d, sleepTime } from '@cetus/utils'
import { fixCoinType } from '@cetusprotocol/common-sdk'
import { useRef } from 'react'
import { v4 } from 'uuid'
import useDeepbookWebSocket from './useDeepbookWebsocket'

const dateType = {
  '1': '1min',
  '10': '10min',
  '15': '15min',
  '30': '30min',
  '60': 'hour',
  '240': '4hour',
  '1D': 'day',
  '1W': 'week'
}

export interface Bar {
  time: number // 时间戳 (秒级)
  open: number
  high: number
  low: number
  close: number
  volume: number
}

// 定义一个全局变量来存储当前的最新请求 ID
let latestRequestId: string | null = null

export default function useGetDeepbookKlineData() {
  // const { setCoinBvPrice } = useProStore()
  const currentPoolId = useRef<any>()
  const unsubscribeRef = useRef<() => void>()
  const { subscribe, send } = useDeepbookWebSocket()
  // 获取历史数据
  const getDeepbookHistoricalData = async ({
    poolId,
    resolution,
    from,
    to,
    firstDataRequest,
    callback,
    onErrorCallback
  }: {
    poolId: string
    resolution: string
    from: number
    to: number
    callback: any
    onErrorCallback: any
    firstDataRequest?: boolean
  }) => {
    console.log('🚀 ~ getDeepbookHistoricalData ~ resolution:', resolution)
    // 对接ws后打开
    // if (currentPoolId.current && currentPoolId.current !== poolId) {
    //   send('UNSUBSCRIBE_OHLCV')
    // }
    currentPoolId.current = poolId

    // 生成当前请求的唯一标识
    const requestId = v4()
    latestRequestId = requestId // 更新全局变量，表明这是最新的请求

    const type = dateType[resolution as keyof typeof dateType]

    const apiUrl = `${envConfigs?.cetus_api}/v3/sui/deepbookv3/prices?date_type=${type}&start_timestamp=${from}&end_timestamp=${to}&address=${poolId}`

    console.log('useGetDeepbookKline apiUrl: ', apiUrl)
    // 内部请求函数
    const fetchData = async (): Promise<Bar[] | null> => {
      try {
        // const response = await fetch(apiUrl, {
        //   method: 'GET',
        //   headers: {
        //     accept: 'application/json'
        //   }
        // })
        const response = await fetch(apiUrl)
        const data = await response.json()
        console.log('🚀 ~ fetchData ~ data:', data)

        if (data?.code === 500) {
          throw new Error('Server Error: 500')
        }

        if (data?.code === 0 && data?.data?.length === 0) {
          return null
        }

        const list = data?.data?.lists || []
        const result = list?.map((item: any) => ({
          time: d(item.timestamp).mul(1000).toNumber(), // 转换为毫秒级时间戳
          high: Number(item.high),
          low: Number(item.low),
          open: Number(item.open),
          close: Number(item.settle)
          // volume: item.volume
        }))

        return result || []
      } catch (error) {
        console.error('getDeepbookHistoricalData 🚀 ~ fetchData Error:', error)

        // 检查当前请求是否是最新请求
        if (latestRequestId !== requestId) {
          console.log('🚀 ~ Request aborted due to poolId change.')
          return [] // 如果不是最新请求，直接返回空数组
        }

        console.log('Retrying in 5 seconds...')
        await sleepTime(5000) // 等待 5 秒后重试

        if (latestRequestId !== requestId) {
          console.log('🚀 ~ Request aborted due to poolId change.')
          return [] // 如果不是最新请求，直接返回空数组
        }

        return await fetchData() // 递归调用
      }
    }

    const list = await fetchData() // 开始请求数据
    if (list) {
      callback(list, { noData: false })
    } else {
      callback([], { noData: true })
    }
  }

  const handleSend = async (action: string, data: any) => {
    const res = send(action, data, { isSubscription: true })

    if (!res) {
      await sleepTime(1000)
      handleSend(action, data)
    }
  }

  // 订阅交易数据
  const subscribeKlineData = ({ poolId, resolution, callback }: { poolId: string; resolution: string; callback: any }) => {
    // console.log(`🚀 ~ subscribeKlineData ~ { poolId, resolution, callback }:`, { poolId, resolution, callback })
    // 先取消之前的订阅
    if (unsubscribeRef.current) {
      // send('UNSUBSCRIBE_OHLCV')
      unsubscribeRef.current()
    }

    // 设置新的订阅
    unsubscribeRef.current = subscribe('pool-price', (data: any) => {
      const value = data?.list?.[data?.list?.length - 1]
      if (!value) return []
      if (fixCoinType(poolId) !== fixCoinType(data?.tokenId)) return []
      const result = {
        time: d(value.timestamp).mul(1000).toNumber(), // 转换为毫秒级时间戳
        high: Number(value.high),
        low: Number(value.low),
        open: Number(value.open),
        close: Number(value.close),
        volume: value.volume
      }

      if (result) {
        callback(result)
        // setCoinBvPrice({
        //   coinType: data?.tokenId,
        //   // price: formatSmallPrice(data?.price, 16)
        //   price: String(result?.close) || ''
        // })
      }
    })

    const data = {
      tokenId: poolId,
      interval: resolution
    }
    // console.log('🚀 ~ subscribeKlineData ~ data:', data)

    // 可以在这里发送初始请求
    handleSend('SUBSCRIBE_OHLCV', data)
  }

  const getLatestKlineData = async ({
    poolId,
    resolution,
    from,
    to,
    firstDataRequest,
    callback,
    onErrorCallback
  }: {
    poolId: string
    resolution: string
    from: number
    to: number
    callback: any
    onErrorCallback: any
    firstDataRequest?: boolean
  }) => {
    try {
      const type = dateType[resolution as keyof typeof dateType]
      // 替换为你的 API 地址
      const apiUrl = `${envConfigs?.cetus_api}/v3/sui/deepbookv3/prices?date_type=${type}&start_timestamp=${from}&end_timestamp=${to}&address=${poolId}`
      console.log('🚀 ~ getDeepbookHistoricalData ~ apiUrl:', apiUrl)
      const response = await fetch(apiUrl, {
        method: 'GET',
        headers: {
          accept: 'application/json'
          // 'x-api-key': '2uZYBhmZMcACCbGxbFLbf5R6QCb'
        }
      })
      const data = await response.json()
      console.log('🚀 ~ getLatestKlineData ~ data:', data)

      const value = data?.data?.lists?.[data?.data?.lists?.length - 1]
      if (!value) return []
      const result = {
        time: d(value.timestamp).mul(1000).toNumber(), // 转换为毫秒级时间戳
        high: Number(value.high),
        low: Number(value.low),
        open: Number(value.open),
        close: Number(value.settle)
      }

      return [result]
    } catch (error) {
      console.log('🚀 ~ getLatestKlineData ~ error:', error)
      return []
    }
  }

  return {
    getDeepbookHistoricalData,
    subscribeKlineData,
    getLatestKlineData
  }
}
